(function(){"use strict";app.factory("tiempoCreditoService",function(n){const i=n.get("mainService"),r="Config/TiempoCredito/",t={};return t.get=function(n){return i.getData("get",r+"?json="+JSON.stringify(n)).then(n=>{if(n.code==="0")throw n;if(n.code==="1")return JSON.parse(n.payload)||[]})},t.save=function(n){return i.getData("post",`${r}?json=${JSON.stringify(n)}`,null,!0)},t.update=function(n,t){return i.getData("put",`${r}${n}?json=${JSON.stringify(t)}`,null,!0)},t.delete=function(n){return i.getData("delete",r+n,null,!0)},t})})(window.angular);